function*naturals(){let n=1;for(;;)yield n++}function take(n,i){const t=[];for(const f of n){if(t.length>=i)break;t.push(f)}return t}function*fibonacci(){let[n,i]=[0,1];for(;;)yield n,[n,i]=[i,n+i]}print("first 5 naturals:",take(naturals(),5).join(","));const fibs=[];for(const n of fibonacci()){if(n>50)break;fibs.push(n)}print("fibonacci under 50:",fibs.join(","));